"""Shared data, Markdown formatting, and URL tracking helpers."""

from __future__ import annotations

import html
import json
import re
from pathlib import Path
from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

ROOT = Path(__file__).resolve().parents[1]
GENERATED_MARKER = (
    "<!-- Generated by scripts/build_readme.py. "
    "Edit site.config.json, content/prompts.json, and generator scripts. -->"
)


def read_json(relative_path: str):
    """Read and parse a UTF-8 JSON file relative to the repository root."""
    return json.loads((ROOT / relative_path).read_text(encoding="utf-8"))


def load_data() -> tuple[dict, list[dict]]:
    """Load site configuration and prompt records."""
    return read_json("site.config.json"), read_json("content/prompts.json")


def localized(value, language: str) -> str:
    """Extract localized text with clean English fallback."""
    if isinstance(value, str):
        return value
    if not isinstance(value, dict):
        return ""
    return str(value.get(language) or value.get("en") or "")


def published(prompts: list[dict]) -> list[dict]:
    """Return published entries sorted newest-first by added_at then id."""
    return sorted(
        (item for item in prompts if item.get("status") == "published"),
        key=lambda item: (item.get("added_at") or "", item.get("id") or ""),
        reverse=True,
    )


def has_copyable_prompt(item: dict) -> bool:
    """Return True when a record contains a public copyable prompt."""
    if item.get("prompt_status") != "public":
        return False
    if str(item.get("short_prompt") or "").strip():
        return True
    structured = item.get("structured_prompt")
    if isinstance(structured, dict):
        return bool(structured)
    return bool(str(structured or "").strip())


def format_structured_prompt(structured) -> str:
    """Format a structured PE object or Markdown/text block for display."""
    if structured is None:
        return ""
    if isinstance(structured, (dict, list)):
        return json.dumps(structured, indent=2, ensure_ascii=False)
    return str(structured).strip()


def repo_url(config: dict) -> str:
    """Build the canonical GitHub repository URL from site.config.json."""
    project = config["project"]
    owner = project["repository_owner"].strip()
    slug = project["repository_slug"].strip()
    return f"https://github.com/{owner}/{slug}"


def is_brand_url(url: str, config: dict) -> bool:
    """Check whether URL belongs to the configured brand website domain."""
    host = (urlsplit(url).hostname or "").lower()
    brand_host = (urlsplit(config["brand"]["home_url"]).hostname or "").lower()
    return bool(brand_host) and (host == brand_host or host.endswith("." + brand_host))


def tracked_url(url: str, placement: str, language: str, config: dict) -> str:
    """Attach UTM campaign attribution to brand website URLs only."""
    if not is_brand_url(url, config):
        return url
    parts = urlsplit(url)
    tracking = dict(config["tracking"])
    tracking["utm_content"] = placement
    tracking["utm_term"] = language
    query = [
        (key, value)
        for key, value in parse_qsl(parts.query, keep_blank_values=True)
        if key not in tracking
    ]
    query.extend(tracking.items())
    return urlunsplit((parts.scheme, parts.netloc, parts.path, urlencode(query), parts.fragment))


def md_text(value) -> str:
    """Escape Markdown table/link special characters."""
    text = str(value).replace("\n", " ").strip()
    for old, new in (("\\", "\\\\"), ("[", "\\["), ("]", "\\]"), ("|", "\\|"), ("<", "&lt;"), (">", "&gt;")):
        text = text.replace(old, new)
    return text


def md_url(url: str) -> str:
    """Escape spaces and parentheses in Markdown link destinations."""
    return url.replace(" ", "%20").replace("(", "%28").replace(")", "%29")


def md_link(label: str, url: str) -> str:
    """Render a safe Markdown hyperlink."""
    return f"[{md_text(label)}]({md_url(url)})"


def code_block(value: str, lang: str = "text") -> str:
    """Render a fenced Markdown code block using an unused backtick length."""
    max_run = max((len(match.group()) for match in re.finditer(r"`+", value)), default=0)
    fence = "`" * max(3, max_run + 1)
    return f"{fence}{lang}\n{value.rstrip()}\n{fence}"


def asset_path(path: str, prefix: str = "") -> str:
    """Resolve a repository-relative path with an optional relative prefix."""
    return path if urlsplit(path).scheme else prefix + path


def html_attr(value) -> str:
    """Escape an HTML attribute value."""
    return html.escape(str(value), quote=True)
